@@ -1 +1,59 @@
 export const pageReady = true;
+
+export function setMenuOpen(button, menu, open) {
+  menu.hidden = !open;
+  button.setAttribute("aria-expanded", String(open));
+}
+
+if (typeof document !== "undefined") {
+  const menuButton = document.querySelector(".menu-toggle");
+  const menu = document.querySelector("#primary-nav");
+  const search = document.querySelector("#project-search");
+  const sort = document.querySelector("#project-sort");
+  const filters = [...document.querySelectorAll(".filter")];
+  const grid = document.querySelector(".projects");
+  const cards = [...document.querySelectorAll(".project-card")];
+  const status = document.querySelector("#result-status");
+  const empty = document.querySelector(".empty-state");
+  let activeFilter = "all";
+
+  menuButton?.addEventListener("click", () => {
+    setMenuOpen(menuButton, menu, menuButton.getAttribute("aria-expanded") !== "true");
+  });
+
+  menu?.addEventListener("click", event => {
+    if (event.target.closest("a") && matchMedia("(max-width: 760px)").matches) setMenuOpen(menuButton, menu, false);
+  });
+
+  function updateProjects() {
+    const query = search.value.trim().toLowerCase();
+    const ordered = [...cards].sort((a, b) => {
+      if (sort.value === "name") return a.dataset.name.localeCompare(b.dataset.name);
+      if (sort.value === "progress") return Number(b.dataset.progress) - Number(a.dataset.progress);
+      return Number(a.dataset.updated) - Number(b.dataset.updated);
+    });
+    ordered.forEach(card => grid.append(card));
+
+    let visible = 0;
+    cards.forEach(card => {
+      const matchesFilter = activeFilter === "all" || card.dataset.status === activeFilter;
+      const matchesSearch = card.textContent.toLowerCase().includes(query);
+      card.hidden = !(matchesFilter && matchesSearch);
+      if (!card.hidden) visible += 1;
+    });
+    status.textContent = `Showing ${visible} project${visible === 1 ? "" : "s"}`;
+    empty.hidden = visible !== 0;
+  }
+
+  filters.forEach(button => button.addEventListener("click", () => {
+    activeFilter = button.dataset.filter;
+    filters.forEach(item => {
+      const selected = item === button;
+      item.classList.toggle("active", selected);
+      item.setAttribute("aria-pressed", String(selected));
+    });
+    updateProjects();
+  }));
+  search?.addEventListener("input", updateProjects);
+  sort?.addEventListener("change", updateProjects);
+}
