diff --git a/styles.css b/styles.css
index 6dbc6af..b434f7f 100644
--- a/styles.css
+++ b/styles.css
@@ -1,3 +1,76 @@
-body { margin: 0; font-family: system-ui, sans-serif; }
-main, header { padding: 1rem; }
-.projects { display: block; }
+:root { color-scheme: light; --ink:#17211b; --muted:#657068; --line:#dfe5df; --paper:#f5f7f3; --white:#fff; --accent:#245c43; --accent-soft:#e5efe9; }
+* { box-sizing:border-box; }
+html { scroll-behavior:smooth; }
+body { margin:0; min-width:320px; background:var(--paper); color:var(--ink); font-family:Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
+button, input, select { font:inherit; }
+button, select { cursor:pointer; }
+a { color:inherit; }
+.sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0; }
+.skip-link { position:fixed; z-index:10; top:.5rem; left:.5rem; padding:.7rem 1rem; border-radius:.5rem; background:var(--ink); color:white; transform:translateY(-150%); }
+.skip-link:focus { transform:none; }
+.site-header { position:relative; z-index:4; display:flex; align-items:center; gap:2rem; min-height:72px; padding:0 clamp(1rem,4vw,4rem); background:rgba(255,255,255,.9); border-bottom:1px solid var(--line); backdrop-filter:blur(12px); }
+.brand { display:flex; align-items:center; gap:.7rem; color:var(--ink); font-weight:760; text-decoration:none; letter-spacing:-.02em; }
+.brand-mark { display:grid; place-items:center; width:34px; height:34px; border-radius:10px; background:var(--ink); color:white; font-size:.68rem; letter-spacing:.04em; }
+.primary-nav { display:flex; gap:.3rem; margin-left:auto; }
+.primary-nav a { padding:.65rem .85rem; border-radius:.55rem; color:var(--muted); font-size:.9rem; font-weight:650; text-decoration:none; }
+.primary-nav a:hover, .primary-nav a.active { background:var(--paper); color:var(--ink); }
+.new-project { display:flex; gap:.65rem; align-items:center; padding:.7rem 1rem; border:0; border-radius:.6rem; background:var(--accent); color:white; font-size:.88rem; font-weight:700; }
+.new-project:hover { background:#174b34; }
+.menu-toggle { display:none; width:42px; height:42px; padding:10px; margin-left:auto; border:1px solid var(--line); border-radius:.6rem; background:white; }
+.menu-toggle span:not(.sr-only) { display:block; height:2px; margin:4px 0; background:var(--ink); }
+main { width:min(1440px,100%); margin:auto; padding:clamp(1.5rem,5vw,4.5rem) clamp(1rem,4vw,4rem) 5rem; }
+.hero { display:flex; justify-content:space-between; align-items:end; gap:2rem; margin-bottom:clamp(2rem,5vw,4rem); }
+.eyebrow, .project-type { margin:0 0 .6rem; color:var(--accent); font-size:.72rem; font-weight:800; letter-spacing:.12em; text-transform:uppercase; }
+h1 { margin:0; font-family:Georgia, "Times New Roman", serif; font-size:clamp(3rem,7vw,6rem); font-weight:500; line-height:.95; letter-spacing:-.055em; }
+.intro { max-width:580px; margin:1.2rem 0 0; color:var(--muted); font-size:clamp(1rem,2vw,1.18rem); line-height:1.6; }
+.summary { display:flex; gap:clamp(1.5rem,4vw,3.5rem); margin:0; padding:1.2rem 0; }
+.summary div { display:flex; flex-direction:column-reverse; gap:.3rem; }
+.summary dt { color:var(--muted); font-size:.75rem; font-weight:700; text-transform:uppercase; }
+.summary dd { margin:0; font-family:Georgia, serif; font-size:2rem; }
+.project-browser { scroll-margin-top:1rem; }
+.toolbar { display:grid; grid-template-columns:minmax(240px,1fr) auto auto; align-items:center; gap:1rem; padding:1rem; border:1px solid var(--line); border-radius:1rem; background:var(--white); }
+.search { position:relative; display:flex; align-items:center; }
+.search svg { position:absolute; left:.9rem; width:19px; fill:none; stroke:var(--muted); stroke-linecap:round; stroke-width:1.8; }
+.search input { width:100%; min-height:44px; padding:.7rem 1rem .7rem 2.7rem; border:1px solid var(--line); border-radius:.65rem; outline:none; color:var(--ink); background:#fbfcfa; }
+.search input:focus, select:focus, button:focus-visible, a:focus-visible { outline:3px solid rgba(36,92,67,.25); outline-offset:2px; }
+.filters { display:flex; gap:.25rem; padding:.25rem; border-radius:.65rem; background:var(--paper); }
+.filter { min-height:38px; padding:.5rem .7rem; border:0; border-radius:.48rem; background:transparent; color:var(--muted); font-size:.82rem; font-weight:700; }
+.filter span { margin-left:.25rem; color:#8a948d; }
+.filter.active { background:white; color:var(--ink); box-shadow:0 1px 4px rgba(23,33,27,.1); }
+.sort { display:flex; align-items:center; gap:.5rem; color:var(--muted); font-size:.75rem; font-weight:700; }
+.sort select { min-height:40px; padding:.5rem 2.1rem .5rem .7rem; border:1px solid var(--line); border-radius:.55rem; background:white; color:var(--ink); }
+.result-status { margin:1.4rem 0 .75rem; color:var(--muted); font-size:.82rem; }
+.projects { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:1rem; }
+.project-card { display:flex; min-height:390px; flex-direction:column; padding:1.35rem; border:1px solid var(--line); border-radius:1rem; background:var(--white); box-shadow:0 8px 30px rgba(23,33,27,.035); transition:transform .2s, box-shadow .2s, border-color .2s; }
+.project-card:hover { transform:translateY(-4px); border-color:#c3cec5; box-shadow:0 16px 38px rgba(23,33,27,.08); }
+.card-top, .progress-row, .project-card footer { display:flex; align-items:center; justify-content:space-between; }
+.project-icon { display:grid; place-items:center; width:48px; height:48px; border-radius:14px; font-family:Georgia,serif; font-size:1.35rem; }
+.coral { background:#fae5db; color:#984c2a; }.blue { background:#ddebf4; color:#32647e; }.green { background:#dcecdf; color:#376548; }.violet { background:#e9e3f2; color:#695184; }
+.status { padding:.38rem .55rem; border-radius:10rem; font-size:.68rem; font-weight:800; }
+.on-track { background:#e6f1e9; color:#2a6845; }.planning { background:#e9edf3; color:#526477; }.needs-attention { background:#f8ead6; color:#945b18; }
+.project-card > div:nth-child(2) { margin:2.2rem 0 auto; }
+.project-card h2, .empty-state h2 { margin:0 0 .6rem; font-family:Georgia,serif; font-size:1.65rem; font-weight:500; }
+.project-card p:not(.project-type) { margin:0; color:var(--muted); font-size:.88rem; line-height:1.55; }
+.progress-row { margin-top:1.8rem; color:var(--muted); font-size:.75rem; }
+.progress-row strong { color:var(--ink); }
+.progress { height:5px; margin:.6rem 0 1.4rem; overflow:hidden; border-radius:1rem; background:#edf0ed; }
+.progress span { display:block; width:var(--progress); height:100%; border-radius:inherit; background:var(--accent); }
+.project-card footer { padding-top:1rem; border-top:1px solid #edf0ed; }
+.project-card time { color:var(--muted); font-size:.7rem; }
+.avatars { display:flex; padding-left:7px; }
+.avatars span { display:grid; place-items:center; width:29px; height:29px; margin-left:-7px; border:2px solid white; border-radius:50%; background:#e8ece8; color:#4d5a51; font-size:.58rem; font-weight:800; }
+.empty-state { padding:5rem 1rem; text-align:center; color:var(--muted); }
+.empty-state > span { display:block; margin-bottom:1rem; font-size:3rem; }
+.empty-state h2 { color:var(--ink); }
+
+@media (min-width:761px) { .primary-nav[hidden] { display:flex; } }
+@media (max-width:1100px) { .projects { grid-template-columns:repeat(2,minmax(0,1fr)); }.toolbar { grid-template-columns:1fr auto; }.sort { grid-column:1/-1; justify-self:end; } }
+@media (max-width:760px) {
+  .site-header { min-height:64px; padding:0 1rem; }.menu-toggle { display:block; }.new-project { display:none; }
+  .primary-nav { position:absolute; top:calc(100% + 1px); left:0; right:0; display:grid; gap:.25rem; margin:0; padding:.75rem 1rem 1rem; background:white; border-bottom:1px solid var(--line); box-shadow:0 12px 20px rgba(23,33,27,.08); }.primary-nav[hidden] { display:none; }
+  main { padding-top:2.5rem; }.hero { display:block; }.summary { margin-top:2rem; border-top:1px solid var(--line); border-bottom:1px solid var(--line); }.summary div { flex:1; }
+  .toolbar { display:flex; align-items:stretch; flex-direction:column; }.filters { overflow-x:auto; }.filter { flex:1; white-space:nowrap; }.sort { justify-content:space-between; }.sort select { flex:1; }
+  .projects { grid-template-columns:1fr; }.project-card { min-height:360px; }
+}
+@media (max-width:420px) { .summary { gap:.6rem; }.summary dd { font-size:1.6rem; }.summary dt { font-size:.65rem; }.project-card { padding:1.15rem; } }
+@media (prefers-reduced-motion:reduce) { html { scroll-behavior:auto; } *,*::before,*::after { transition-duration:.01ms!important; animation-duration:.01ms!important; } }
